pug:
table.sys-two-columns--box(role="presentation" width="100%")
    tr
        td.sys-two-columns--col(style="padding:{{ padding_left }};text-align:{{ align }}")
            p.sys-two-columns--head(style="color:{{ title_color }}") {{ left_title }}
            p.sys-two-columns--body(style="color:{{ text_color }}") {{ left_text }}
        td.sys-two-columns--col(style="padding:{{ padding_right }};text-align:{{ align }}")
            p.sys-two-columns--head(style="color:{{ title_color }}") {{ right_title }}
            p.sys-two-columns--body(style="color:{{ text_color }}") {{ right_text }}
